import { Component, createEffect, createSignal, For, untrack } from "solid-js";

import { RadioButton } from "#core/ui-next/components/radio-button.jsx";
import { SimpleButton } from "#core/ui-next/debug/simple-button.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { createArraySignal } from "#core/ui-next/utilities/solid-utilities.js";

export interface IModelProxy {
	value: object;
	readonly name: string;
	readonly id: number;
}

export interface ObjectEditorProps {
	proxy?: IModelProxy;
	class: string;
}

const ObjectHistoryComponent: Component<ObjectEditorProps> = (props) => {
	const [autoRefresh, setAutoRefresh] = createSignal(false);

	const [history, useHistory] = createArraySignal<string>();
	const [maxHistory, setMaxHistory] = createSignal(10);

	createEffect(() => {
		if (autoRefresh() && props.proxy) {
			const json = JSON.stringify(props.proxy.value, null, 2);
			untrack(() => {
				useHistory((history) => {
					if (history.length < maxHistory()) {
						history.unshift();
					}

					history.push(`${Date.now()}\n${json}`);
				});
			});
		}
	});

	return (
		<div class={`flex flex-col ${props.class ?? ""}`}>
			<div class="flex flex-row">
				<RadioButton
					class="mx-1 my-2"
					isChecked={autoRefresh()}
					onActivate={() => setAutoRefresh((v) => !v)}
				>
					Auto
				</RadioButton>
				<div class="flex flex-row items-center justify-center">
					<SimpleButton
						class="m-2"
						onActivate={() => setMaxHistory((v) => v - 1)}
					>
						&lt;
					</SimpleButton>
					Max History: {maxHistory()}{" "}
					<SimpleButton
						class="m-2"
						onActivate={() => setMaxHistory((v) => v + 1)}
					>
						&gt;
					</SimpleButton>
				</div>
			</div>
			<div class="flex flex-col flex-auto">
				<For each={history()}>{(entry) => <div style={{ "white-space": "pre" }}>{entry}</div>}</For>
			</div>
		</div>
	);
};

export const ObjectHistory = ComponentRegistry.register({
	name: "ObjectHistory",
	createInstance: ObjectHistoryComponent,
});
